        "code": {
          "text": "Intermittent coughing with drinks"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Intermittent coughing, especially when drinking quickly; possible microaspiration. No history of aspiration pneumonia in the EMR."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-4",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-4",
        "status": "final",
        "code": {
          "text": "Hoarse voice"
