        "code": {
          "text": "Fatigue and reduced exercise tolerance"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Marked fatigue; reports being exhausted by hanging out washing and needing rests with light tasks. Can walk approximately 5–10 minutes on flat ground before needing to rest."
