        "resourceType": "Observation",
        "id": "observation-6",
        "status": "final",
        "code": {
          "text": "Exertional shortness of breath"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Breathless when rushing or after 5–10 minutes of walking on flat ground. Able to speak in full sentences on the phone. Denies waking short of breath."
      }
