      "resource": {
        "resourceType": "Observation",
        "id": "observation-10",
        "status": "final",
        "code": {
          "text": "Functional ability with activities of daily living"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Independent with personal ADLs but slower; sits on a plastic chair to shower due to fatigue. Does own shopping if taking time and often takes a taxi because walking from the bus stop is too much. Unable to manage heavy house or yard work, including mowing the lawn."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-11",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-11",
        "status": "final",
        "code": {
          "text": "Mood and suicidal ideation"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Reports decreased mood and some social withdrawal; denies suicidal ideation."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-12",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-12",
        "status": "final",
        "code": {
          "text": "Cognition and recall"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Oriented but forgetful, with poor recall of treatment and medication sequence and difficulty recalling dates; answers were sometimes contradictory."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-13",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-13",
        "status": "final",
        "code": {
          "text": "Telephone examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Sounded tired but not in acute distress; coherent speech in full sentences. No audible stridor or wheeze over the phone."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-14",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-14",
        "status": "final",
        "code": {
          "text": "Airway and respiratory symptoms by history"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Denies stridor, stertor, drooling, cough, haemoptysis, and fever. No acute severe shortness of breath reported."
